def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def find_path(row, col, path):
        if (row, col) == goal:
            return path + [(row, col)]

        grid[row] = grid[row][:col] + '#' + grid[row][col+1:] 

        neighbors = [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]

        for r, c in neighbors:
            if is_valid(r, c) and (r, c) not in path:
                result = find_path(r, c, path + [(row, col)])
                if result:
                    return result

        grid[row] = grid[row][:col] + '.' + grid[row][col+1:]
        return None

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    path = find_path(start[0], start[1], [])
    return path if path else []
